{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be an object')
    if 'nodes' not in case or 'required_symbols' not in case:
        raise ValueError('missing required fields')
    nodes = case['nodes']
    required = case['required_symbols']
    if not isinstance(nodes, list) or not nodes:
        raise ValueError('nodes must be a non-empty list')
    if not isinstance(required, list) or any(not isinstance(s, str) for s in required):
        raise ValueError('required_symbols must be a list of strings')

    fields = ('id', 'parent', 'symbol', 'depth', 'removable', 'utility')
    by_id = {}
    positions = {}
    for pos, node in enumerate(nodes):
        if not isinstance(node, dict) or any(field not in node for field in fields):
            raise ValueError('invalid node')
        node_id = node['id']
        parent = node['parent']
        symbol = node['symbol']
        depth = node['depth']
        removable = node['removable']
        utility = node['utility']
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError('node ids must be unique strings')
        if parent is not None and not isinstance(parent, str):
            raise ValueError('invalid parent')
        if not isinstance(symbol, str) or isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError('invalid node metadata')
        if not isinstance(removable, bool) or isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError('invalid node metadata')
        by_id[node_id] = node
        positions[node_id] = pos

    roots = [node for node in nodes if node['parent'] is None]
    if len(roots) != 1 or roots[0]['depth'] != 0:
        raise ValueError('invalid tree root')
    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            if parent not in by_id or node['depth'] != by_id[parent]['depth'] + 1:
                raise ValueError('invalid tree relationship')
            children[parent].append(node['id'])

    root_id = roots[0]['id']
    seen = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError('cyclic tree')
        seen.add(node_id)
        stack.extend(reversed(children[node_id]))
    if len(seen) != len(nodes):
        raise ValueError('disconnected tree')

    active = set(by_id)
    symbol_counts = {}
    for node in nodes:
        symbol_counts[node['symbol']] = symbol_counts.get(node['symbol'], 0) + 1
    required_set = set(required)
    removed = []
    candidates = sorted(
        (node for node in nodes if node['removable']),
        key=lambda node: (-node['depth'], node['id'])
    )
    for node in candidates:
        node_id = node['id']
        if node_id not in active or node_id == root_id or node['symbol'] in required_set:
            continue
        if any(child in active for child in children[node_id]):
            continue
        if symbol_counts[node['symbol']] <= 1 and node['symbol'] in required_set:
            continue
        active.remove(node_id)
        symbol_counts[node['symbol']] -= 1
        removed.append(node_id)

    retained = sorted(active)
    return {'removed_node_ids': removed, 'retained_node_ids': retained}"}
